-- ONE schema. GENERATED by scripts/db/gen.ts from apps/web/src/data/schema.ts. Do not edit by hand.
-- Every table: id, user_id (RLS owner), created_at, updated_at (client clock, last-write-wins),
-- synced_at (server clock, used for incremental pulls), deleted_at (soft delete).


create or replace function public.one_touch() returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' and new.updated_at < old.updated_at then
    return old; -- last-write-wins: ignore stale writes
  end if;
  new.synced_at := now();
  if new.updated_at is null then new.updated_at := now(); end if;
  return new;
end $$;

